sql:
select *
from (
    select quarter(end_date) end_quarter, count(distinct monthly_fee) unique_plans
    from subscriptions
    group by quarter(end_date)
) t
where unique_plans > 7
order by end_quarter desc
limit 10;

select distinct merchant, txn_type
from transactions
where txn_type = 'FEE';

SELECT id, merchant, amount
FROM transactions
WHERE account_id IN (20, 32) OR amount <= 3300;

select *
from web_events
where duration_sec > 165 and session_id in (10, 17, 34, 36);

select e.email as employee_email, m.job_title as manager_job_title
from employees e
join employees m on e.manager_id = m.id;

SELECT tags, launch_date, price
FROM products
WHERE brand IN ('Umbrella', 'Acme', 'Initech') AND (launch_date < '2024-03-01' OR brand = 'Acme');

SELECT id, dept_id, full_name
FROM employees
WHERE level NOT IN ('L4', 'L5') AND (hire_date <= '2024-09-04' OR job_title <> 'Analyst');

select *, concat_ws('/', method, status) as method_status_key, case when status = 'FAILED' then 1 else 0 end as is_failed
from payments
where amount <= 1500;

select a.id, a.account_type
from accounts a
where a.opened_date <= '2024-09-01' and exists (select 1 from transactions t where t.account_id = a.id);

SELECT id, customer_id, UPPER(plan) AS plan_upper
FROM subscriptions
WHERE customer_id IS NOT NULL;

SELECT cost, CASE WHEN cost >= 87 THEN 'High' WHEN cost >= 18 THEN 'Medium' ELSE 'Low' END AS cost_tier
FROM shipments
WHERE delivered_date >= '2023-03-01' AND YEAR(delivered_date) >= 2024;

SELECT *, amount * discount AS amount_times_discount
FROM orders
WHERE channel IS NOT NULL;

select *
from (
    select date_trunc('MONTH', sale_date) sale_month, min(sale_date) first_sale_date, sum(revenue) total_revenue
    from store_sales
    group by date_trunc('MONTH', sale_date)
) agg
where total_revenue < 18000
order by first_sale_date desc;

select quarter(txn_time) as txn_quarter, concat_ws(', ', sort_array(collect_set(merchant))) as merchant_values, max(amount) as max_amount
from transactions
group by quarter(txn_time);

select session_id, case when duration_sec >= 434 then 'high' when duration_sec >= 82 then 'mid' else 'low' end duration_sec_bucket, max(duration_sec) - min(duration_sec) duration_sec_range
from web_events
group by session_id, case when duration_sec >= 434 then 'high' when duration_sec >= 82 then 'mid' else 'low' end;

SELECT status, DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_month, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values
FROM accounts
GROUP BY status, DATE_FORMAT(opened_date, 'yyyy-MM');

SELECT DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_month, MAX(opened_date) AS last_opened_date
FROM accounts
GROUP BY DATE_FORMAT(opened_date, 'yyyy-MM');

SELECT p.id, p.method
FROM payments p
WHERE p.amount BETWEEN 500 AND 1400 AND p.order_id IN (SELECT id FROM orders WHERE channel IN ('store', 'web'));

SELECT id, store_name
FROM stores
WHERE sqft = 10336;

SELECT units
FROM store_sales
WHERE units != 24;

SELECT id, country
FROM suppliers
WHERE city = 'Tokyo';

select unit_price
from order_items
where quantity >= 3 and unit_price <= 250;

SELECT id, session_id
FROM web_events
WHERE duration_sec > 224;

SELECT id, dept_name
FROM departments
WHERE location = 'Bangkok' AND budget < 3094000 AND budget <= 2939000;

SELECT id, is_flagged, account_id
FROM transactions
WHERE amount <= 3100 AND amount >= 3800;

SELECT country, segment
FROM customers
WHERE city <> 'London';

SELECT id, shipping_fee
FROM orders
WHERE discount < 0.31;

SELECT id, discount, customer_id
FROM orders
WHERE status <> 'RETURNED';

SELECT s.device, c.segment, c.email
FROM sessions s
LEFT JOIN customers c ON s.customer_id = c.id;

SELECT s.order_id, o.channel
FROM shipments s
LEFT JOIN orders o ON s.order_id = o.id;

SELECT s.supplier_name, p.price
FROM suppliers s
LEFT OUTER JOIN products p ON s.id = p.supplier_id;

SELECT a.customer_id, t.txn_type
FROM accounts a
LEFT JOIN transactions t ON t.account_id = a.id;

SELECT o.shipping_fee, s.delivered_date, s.shipped_date
FROM orders o
LEFT OUTER JOIN shipments s ON o.id = s.order_id;

SELECT s.store_name, ss.product_id, ss.units
FROM stores s
LEFT JOIN store_sales ss ON ss.store_id = s.id;

SELECT p.product_name, ss.store_id
FROM products p
LEFT JOIN store_sales ss ON p.id = ss.product_id;

SELECT departments.dept_name, departments.location, employees.dept_id
FROM departments
LEFT JOIN employees ON departments.id = employees.dept_id;

SELECT *, SUBSTRING(plan, 1, 3) plan_prefix
FROM subscriptions
WHERE MONTH(start_date) IN (5, 7, 10) AND end_date > '2023-06-01';

select s.id, s.country, s.city
from suppliers s
where exists (select 1 from products p where p.supplier_id = s.id and p.supplier_id in (17, 37));

SELECT stores.id, stores.city
FROM stores
WHERE EXISTS (SELECT 1 FROM inventory WHERE inventory.store_id = stores.id AND inventory.store_id IN (1, 6));

SELECT s.id, s.store_name
FROM stores s
WHERE EXISTS (SELECT 1 FROM orders o WHERE o.store_id = s.id AND o.customer_id IS NULL);

select c.id, c.city, c.country
from customers c
where exists (select 1 from orders o where o.customer_id = c.id);

select s.id, s.started_at
from sessions s
where exists (select 1 from web_events we where we.session_id = s.id);

SELECT a.id, a.account_type
FROM accounts a
WHERE EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id);

SELECT s.id, s.country, s.rating
FROM suppliers s
WHERE EXISTS (SELECT 1 FROM products p WHERE p.supplier_id = s.id);

SELECT accounts.id, accounts.customer_id, accounts.status
FROM accounts
WHERE EXISTS (SELECT 1 FROM transactions WHERE transactions.account_id = accounts.id AND transactions.account_id = 12);

SELECT d.id, d.location, d.dept_name
FROM departments d
WHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id);

SELECT d.id, d.dept_name, d.location
FROM departments d
WHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id AND e.full_name NOT LIKE 'Ol%');

SELECT sessions.id, sessions.country, sessions.started_at
FROM sessions
WHERE EXISTS (SELECT 1 FROM web_events WHERE web_events.session_id = sessions.id AND HOUR(web_events.event_time) BETWEEN 7 AND 10);

SELECT store_id, COALESCE(quantity, 0) quantity_filled
FROM inventory
WHERE product_id IN (3, 4, 9, 10) AND quantity >= 210;

select id, account_id, amount
from (
    select *, dense_rank() over (partition by account_id order by amount) pos
    from transactions
) r
where pos <= 3;

select id, supplier_id, price
from (
    select *, row_number() over (partition by supplier_id order by price desc, id) as row_num
    from products
) as t
where row_num = 1;

select id, product_id, units
from (
    select
        id,
        product_id,
        units,
        row_number() over (partition by product_id order by units desc, id) as rnk
    from store_sales
) as t
where rnk <= 3;

SELECT id, job_title, salary
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY job_title ORDER BY salary DESC, id) AS pos
    FROM employees
) AS r
WHERE pos <= 3;

SELECT *
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY start_date DESC, id) rnk
    FROM subscriptions
) t
WHERE rnk = 1;

SELECT *
FROM (
    SELECT *, RANK() OVER (PARTITION BY brand ORDER BY stock_qty DESC) AS rnk
    FROM products
) AS ranked
WHERE rnk <= 2;

select id, brand, stock_qty
from (
    select *, row_number() over (partition by brand order by stock_qty, id) as row_num
    from products
) as ranked
where row_num = 1;

SELECT *
FROM (
    SELECT *, DENSE_RANK() OVER (PARTITION BY txn_type ORDER BY amount DESC) AS rnk
    FROM transactions
) AS r
WHERE rnk <= 5;

SELECT id, product_id, units
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY units, id) AS rnk
    FROM store_sales
) AS t
WHERE rnk <= 1;

select id, txn_type, txn_time
from (
    select
        id,
        txn_type,
        txn_time,
        rank() over (partition by txn_type order by txn_time desc) rn
    from transactions
) r
where rn = 1;

select *
from (
    select
        id,
        account_id,
        amount,
        row_number() over (partition by account_id order by amount, id) as pos
    from transactions
) as t
where pos <= 5;

SELECT *
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY revenue DESC, id) AS rnk
    FROM store_sales
) AS ranked
WHERE rnk = 1;

select id, session_id, duration_sec
from (
    select *, row_number() over (partition by session_id order by duration_sec desc, id) as rnk
    from web_events
) as r
where rnk = 1;

SELECT id, country, rating
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY rating DESC, id) AS pos
    FROM suppliers
) AS ranked
WHERE pos <= 3;

SELECT *
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY cost, id) rn
    FROM shipments
) r
WHERE rn <= 3;

select *
from (
    select *, row_number() over (partition by page order by event_time, id) as rn
    from web_events
) as ranked
where rn <= 2;

select id, order_id, unit_price
from (
    select
        id,
        order_id,
        unit_price,
        row_number() over (partition by order_id order by unit_price desc, id) as row_num
    from order_items
) as ranked
where row_num <= 5;

SELECT *
FROM (
    SELECT *, DENSE_RANK() OVER (PARTITION BY status ORDER BY amount DESC) AS rn
    FROM orders
) AS ranked
WHERE rn <= 2;

select *
from (
    select
        id,
        status,
        monthly_fee,
        row_number() over (partition by status order by monthly_fee desc, id) as rnk
    from subscriptions
) as r
where rnk <= 3;

SELECT *
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY balance DESC, id) AS pos
    FROM accounts
) AS t
WHERE pos <= 1;

select
    id,
    city,
    rating,
    country
from (
    select *, row_number() over (partition by city order by rating, id) as pos
    from suppliers
) as r
where pos = 1;

select id, session_id
from web_events
where not (page = '/cart' and event_type in ('page_view', 'purchase', 'search'));
